 bool SharedItemMenuJ(InventoryHit item){EntityMenuJ(new(item.Id,true,item.Hangar));return true;}
 void ColumnMenuJ(DesktopWindow w,string id){var c=w.ColumnsJ.First(v=>v.Id==id);var actions=new List<(string,Action)>{("Move column left",()=>{int i=w.ColumnsJ.IndexOf(c);if(i>0){w.ColumnsJ.Remove(c);w.ColumnsJ.Insert(i-1,c);}SaveDesktop();}),("Move column right",()=>{int i=w.ColumnsJ.IndexOf(c);if(i<w.ColumnsJ.Count-1){w.ColumnsJ.Remove(c);w.ColumnsJ.Insert(i+1,c);}SaveDesktop();})};foreach(var col in w.ColumnsJ){var target=col;actions.Add(((col.Visible?"Hide ":"Show ")+col.Label,()=>{if(target.Visible&&w.ColumnsJ.Count(v=>v.Visible)==1){world.Say("Keep at least one column visible.");return;}target.Visible=!target.Visible;SaveDesktop();}));}ShowPopup("Overview columns",actions);}
 void DrawSettingsJ(DesktopWindow w){int x=w.X+16,y=w.Y+44,width=w.Width-32;SearchFieldJ(w,new(x,y,width-300,30),"Find a window...");ui.Button(new(x+width-290,y,140,30),"NEW INVENTORY",()=>NewInstanceJ(ViewMode.Inventory));ui.Button(new(x+width-142,y,142,30),"NEW OVERVIEW",()=>NewInstanceJ(ViewMode.OverviewJ));y+=46;ui.Text("Window                         State                 Actions",x,y,Cyan,12);y+=27;var kinds=Enum.GetValues<ViewMode>().Where(k=>k is not(ViewMode.Title or ViewMode.Station or ViewMode.Space)&&WindowTitle(k).Contains(w.QueryJ,StringComparison.OrdinalIgnoreCase)).ToArray();int visible=Math.Max(1,(w.Height-180)/32);w.ScrollJ=Math.Clamp(w.ScrollJ,0,Math.Max(0,kinds.Length-visible));for(int i=0;i<visible&&i+w.ScrollJ<kinds.Length;i++){var kind=kinds[i+w.ScrollJ];int row=y+i*32;ui.Box(new(x,row,width-18,30),i%2==0?new Color(19,29,35):new Color(15,24,30));ui.Text(ShortInfo(WindowTitle(kind),42),x+8,row+8,White,12);ui.Text(desktop.Any(v=>v.Kind==kind)?"Open":"Closed",x+350,row+8,Muted,12);ui.Button(new(x+440,row+3,100,24),"OPEN",()=>EnsureWindow(kind));var existing=desktop.LastOrDefault(v=>v.Kind==kind);if(existing!=null){var target=existing;ui.Button(new(x+550,row+3,110,24),"OPTIONS",()=>WindowMenuJ(target));}}DrawScrollbarJ(w,new(w.Bounds.Right-17,y,9,visible*32),kinds.Length,visible);ui.Text("Alt+F11 opens this window. Header ...: lock, compact, opacity, stack, duplicate.",x,w.Bounds.Bottom-52,Muted,12);ui.Text("Mouse wheel scrolls. Double-click header collapses. Drag near edges to snap.",x,w.Bounds.Bottom-31,Muted,12);}
 void DrawScrollbarJ(DesktopWindow w,Rectangle r,int count,int visible){ui.Box(r,new Color(8,15,20));int height=count<=visible?r.Height:Math.Max(20,r.Height*visible/Math.Max(1,count));int travel=r.Height-height,y=r.Y+(count<=visible?0:travel*w.ScrollJ/Math.Max(1,count-visible));ui.Box(new(r.X,y,r.Width,height),new Color(76,103,118));ui.Hits.Add(new(r,()=>{w.ScrollJ=count<=visible?0:Math.Clamp((int)((mouse.Y-r.Y)/(float)Math.Max(1,r.Height)*(count-visible)),0,count-visible);},"Scroll list"));}
 void DrawOverviewJ(DesktopWindow w){if(w.ColumnsJ.Count==0)w.ColumnsJ=[new(){Id="name",Label="Name",Width=150},new(){Id="distance",Label="Distance",Width=90},new(){Id="type",Label="Type",Width=110}];int x=w.X+8,y=w.Y+38,header=w.Compact?24:30;string[] presets=["All","Hostiles","Resources","Containers"];for(int i=0;i<presets.Length;i++){string preset=presets[i];ui.Button(new(x+i*(w.Width-16)/4,y,(w.Width-20)/4,24),preset,()=>{w.PresetJ=preset;w.ScrollJ=0;SaveDesktop();},active:w.PresetJ==preset);}y+=31;SearchFieldJ(w,new(x,y,w.Width-16,28),"Filter overview...");y+=35;int cx=x;foreach(var col in w.ColumnsJ.Where(c=>c.Visible)){var c=col;var rect=new Rectangle(cx,y,c.Width,header);ui.Button(rect,c.Label+(w.SortJ==c.Id?(w.DescendingJ?" v":" ^"):""),()=>{if(w.SortJ==c.Id)w.DescendingJ=!w.DescendingJ;else{w.SortJ=c.Id;w.DescendingJ=false;}SaveDesktop();},"Column / "+c.Id);var edge=new Rectangle(rect.Right-4,rect.Y,4,rect.Height);ui.Hits.Add(new(edge,()=>{resizeColumnJ=c;resizeColumnOwnerJ=w;columnOriginJ=mouse.X;columnWidthJ=c.Width;},"Resize column / "+c.Id));cx+=c.Width;}y+=header+2;var targets=world.Targets.Where(t=>t.Alive&&t.Name.Contains(w.QueryJ,StringComparison.OrdinalIgnoreCase)&& (w.PresetJ=="All"||w.PresetJ=="Hostiles"&&t.Kind==TargetKind.Raider||w.PresetJ=="Resources"&&t.Kind==TargetKind.Asteroid||w.PresetJ=="Containers"&&t.Kind is TargetKind.Container or TargetKind.Wreck));targets=w.SortJ switch{"name"=>targets.OrderBy(t=>t.Name),"type"=>targets.OrderBy(t=>t.Kind),_=>targets.OrderBy(t=>Vector3.DistanceSquared(t.Position,world.Player.Position))};if(w.DescendingJ)targets=targets.Reverse();var rows=targets.ToArray();int rowHeight=w.Compact?24:30,visible=Math.Max(1,(w.Bounds.Bottom-y-33)/rowHeight);w.ScrollJ=Math.Clamp(w.ScrollJ,0,Math.Max(0,rows.Length-visible));for(int i=0;i<visible&&i+w.ScrollJ<rows.Length;i++){var t=rows[i+w.ScrollJ];int row=y+i*rowHeight;var rect=new Rectangle(x,row,w.Width-26,rowHeight-1);ui.Box(rect,t.Id==world.SelectedId?new Color(40,65,77):i%2==0?new Color(20,29,35):new Color(14,24,30));int tx=x;foreach(var c in w.ColumnsJ.Where(c=>c.Visible)){string text=c.Id switch{"name"=>t.Name,"type"=>t.Kind.ToString(),_=>SolarCatalog.Distance(Vector3.Distance(t.Position,world.Player.Position))};ui.Text(ShortInfo(text,Math.Max(4,c.Width/7)),tx+5,row+6,t.Kind==TargetKind.Raider?Red:White,12);tx+=c.Width;}var entity=new UiEntityJ(t.Id,false);ui.Hits.Add(new(rect,()=>ExecuteCommandJ(entity,"select"),"J entity / "+t.Id));}DrawScrollbarJ(w,new(w.Bounds.Right-14,y,8,visible*rowHeight),rows.Length,visible);ui.Text(rows.Length+" objects / "+w.PresetJ,x,w.Bounds.Bottom-25,Muted,11);}
 void SetupCaptureJ(){desktop.Clear();world.Screen=ViewMode.Station;world.Grid="station";world.Hangar["ammo"]=12;world.Hangar["miner"]=1;world.Hangar["ore"]=500;world.WalletFunds=100000;var cargo=NewInstanceJ(ViewMode.Inventory);cargo.X=90;cargo.Y=110;cargo.Width=690;cargo.Height=570;cargo.InventoryHangarJ=false;var hangar=NewInstanceJ(ViewMode.Inventory);hangar.X=810;hangar.Y=110;hangar.Width=690;hangar.Height=570;hangar.InventoryHangarJ=true;if(captureScene=="stage-j-settings"){desktop.Clear();EnsureWindow(ViewMode.DesktopSettingsJ);}if(captureScene=="stage-j-overview"){world.Undock();world.EnterGrid("belt",false);desktop.Clear();var a=NewInstanceJ(ViewMode.OverviewJ);a.X=760;a.Y=110;a.PresetJ="Hostiles";var b=NewInstanceJ(ViewMode.OverviewJ);b.X=240;b.Y=110;b.PresetJ="Resources";}SaveDesktop();}
}
